import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
// eslint-disable-next-line no-unused-vars
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedBackground from '../components/AnimatedBackground';
import api from '../utils/api';
const Login = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const { user, login, register, checkAuth } = useAuth();

    const [isLogin, setIsLogin] = useState(true);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        confirmPassword: ''
    });

    // 2FA State
    const [require2FA, setRequire2FA] = useState(false);
    const [userId, setUserId] = useState(null);
    const [twoFactorCode, setTwoFactorCode] = useState('');

    // Redirect if already logged in
    useEffect(() => {
        if (user) {
            const from = location.state?.from?.pathname || '/';
            navigate(from);
        }
    }, [user, navigate, location]);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        setSuccess('');

        try {
            if (isLogin) {
                if (require2FA) {
                    // Verify 2FA
                    await api.post('/two-factor/validate', {
                        userId,
                        token: twoFactorCode
                    });

                    // Refresh auth state and redirect
                    await checkAuth();
                    const fromObj = location.state?.from || { pathname: '/' };
                    navigate(fromObj.pathname || '/', { state: fromObj.state });
                    return;
                }

                const response = await login(formData.email, formData.password);

                if (response.require2FA) {
                    setRequire2FA(true);
                    setUserId(response.userId);
                    setLoading(false);
                    return;
                }

                // Normal login success - redirect
                const fromObj = location.state?.from || { pathname: '/' };
                navigate(fromObj.pathname || '/', { state: fromObj.state });
            } else {
                // Registration
                if (formData.password !== formData.confirmPassword) {
                    setError('Passwords do not match');
                    setLoading(false);
                    return;
                }
                const result = await register(formData.name, formData.email, formData.password);
                if (result.success) {
                    setSuccess('Account created! Please login with your credentials.');
                    setIsLogin(true);
                    setFormData({ name: '', email: formData.email, password: '', confirmPassword: '' });
                }
            }
        } catch (err) {
            setError(err.response?.data?.message || err.message || 'Something went wrong');
        } finally {
            setLoading(false);
        }
    };

    const handleGoogleLogin = () => {
        window.location.href = `${API_URL}/auth/google`;
    };

    const toggleMode = () => {
        setIsLogin(!isLogin);
        setError('');
        setSuccess('');
